import { cacheLife } from "next/cache";
import { Box } from "@chakra-ui/react";
import { getApiDocs } from "@/lib/swagger";
import ReactSwagger from "./react-swagger";

export default async function IndexPage() {
  "use cache";
  // getApiDocs() reads the pre-built public/openapi-spec.json in production
  // (generated by `openapi:build` before `next build`), so this is static
  // build output, not per-request data - safe to bake into the shell.
  cacheLife("max");
  const spec = await getApiDocs();
  return (
    <Box as="section" className="container">
      <ReactSwagger spec={spec} />
    </Box>
  );
}
